window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[192]={"id":"192","numero":192,"titre":"Pathologies auto-immunes","objectifs":[{"id":"192-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’auto-immunité","contenu":"<p>L'<span class=\"kw-def\">auto-immunité</span> est un <strong>phénomène physiologique naturel</strong> : le système immunitaire produit en permanence des <span class=\"kw-bio\">auto-anticorps</span> et des <span class=\"kw-bio\">lymphocytes auto-réactifs</span>, contrôlés en continu par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">mécanismes de tolérance</span> vis-à-vis des antigènes du soi. L'<span class=\"kw-etio\">auto-immunité</span> n'est donc <strong>pas</strong> synonyme de maladie.</p>\n      <p>La <span class=\"kw-def\">maladie auto-immune (MAI)</span> résulte d'une <strong><span class=\"kw-alerte\">rupture</span> des mécanismes de tolérance</strong>. Elle associe :</p>\n      <ul>\n        <li>une <strong>conséquence</strong> de la réaction immunitaire contre <span class=\"kw-clinique\">les</span> antigènes du soi — signes <span class=\"kw-clinique\">cliniques</span>, <span class=\"kw-bio\">biologiques</span>, <span class=\"kw-imagerie\">histologiques ou d'imagerie</span> ;</li>\n        <li>la présence d'<span class=\"kw-bio\">auto-anticorps</span> et/ou de <span class=\"kw-bio\">lymphocytes auto-réactifs</span> dans un organe atteint (signes biologiques ou histologiques d'<span class=\"kw-etio\">auto-immunité</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège majeur.</strong> La seule présence de signes biologiques (auto-anticorps) <span class=\"kw-alerte\">sans signe clinique, histologique ou d'imagerie</span> est <strong>insuffisante</strong> pour porter le diagnostic de MAI : toute stimulation du système immunitaire (infection notamment) peut générer des auto-anticorps. Nuance : l'<span class=\"kw-etio\">auto-immunité</span> pathologique <em>précède</em> souvent l'apparition des signes cliniques.\n      </div>\n      <p>Une <strong><span class=\"kw-alerte\">MAI sévère</span></strong> se définit par l'existence de lésions d'<strong>organes « nobles »</strong> — <span class=\"kw-alerte\">rein, poumon, SNC, SNP, cœur, tube digestif, système hématopoïétique</span>. Elle doit être recherchée systématiquement devant toute MAI : elle peut engager le <span class=\"kw-alerte\">pronostic vital</span> et justifie un traitement agressif.</p>","frequence":0},{"id":"192-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la prévalence globale des maladies auto-immunes (MAI) et grandes notions épidémiologiques fondamentales (âge, sexe)","contenu":"<p>La <span class=\"kw-def\">prévalence</span> globale des MAI est de <span class=\"kw-chiffre\">5 à 10 %</span> de la population, un chiffre <strong>en augmentation</strong> ces dernières décennies. <span class=\"kw-clinique\">Les</span> MAI représentent la <strong>3ᵉ cause de <span class=\"kw-def\">morbidité</span></strong> dans les pays développés.</p>\n      <ul>\n        <li><strong>Âge</strong> : âge moyen de début ≈ <span class=\"kw-chiffre\">50 ans</span>, mais très variable selon le type de MAI.</li>\n        <li><strong>Sexe</strong> : nette <strong>prédominance féminine</strong> (<span class=\"kw-chiffre\">80 %</span> des cas).</li>\n      </ul>\n      <p>Ordre de fréquence (classement de médecine interne) :</p>\n      <table >\n        <thead><tr><th>Fréquence</th><th>Maladies auto-immunes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquentes</strong></td><td><span class=\"kw-def\">Polyarthrite rhumatoïde</span> ; pathologies thyroïdiennes auto-immunes ; <span class=\"kw-def\">sclérose en plaques</span></td></tr>\n          <tr><td><strong>Relativement fréquentes</strong></td><td>Syndrome de <span class=\"kw-def\">Gougerot-Sjögren</span> ; <span class=\"kw-etio\">maladie cœliaque</span> ; <span class=\"kw-def\">diabète de type 1</span></td></tr>\n          <tr><td><strong>Rares</strong></td><td>Toutes <span class=\"kw-clinique\">les</span> autres MAI — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">&lt; 1/2000</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"192-3","rang":"A","rubrique":"Définition","titre":"Citer des exemples de MAI spécifique d’organe et systémiques","contenu":"<p><span class=\"kw-clinique\">Les</span> MAI se répartissent en deux grands groupes, selon que l'atteinte vise <strong>un organe précis</strong> ou se manifeste de façon <strong>systémique</strong>.</p>\n      <table >\n        <thead><tr><th>MAI spécifiques d'organe</th><th>MAI non spécifiques d'organe (systémiques)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Glandes endocrines :</strong> <span class=\"kw-def\">thyroïdite de Hashimoto</span> ; <span class=\"kw-def\">maladie de Basedow</span> ; <span class=\"kw-def\">maladie d'Addison</span> ; <span class=\"kw-def\">diabète de type 1</span> ; ovarite <span class=\"kw-etio\">auto-immune</span><br>\n              <strong>Foie et tube digestif :</strong> <span class=\"kw-def\">hépatites auto-immunes</span> ; <span class=\"kw-def\">cirrhose biliaire primitive</span> ; <span class=\"kw-def\">maladie de Biermer</span> ; <span class=\"kw-def\">maladie cœliaque</span><br>\n              <strong>Système nerveux :</strong> <span class=\"kw-def\">myasthénie</span> ; <span class=\"kw-def\">syndrome de Lambert-Eaton</span> ; <span class=\"kw-def\">syndrome de Guillain-Barré</span> ; <span class=\"kw-def\">sclérose en plaques</span><br>\n              <strong>Œil :</strong> ophtalmie sympathique<br>\n              <strong>Peau :</strong> <span class=\"kw-def\">pemphigus</span> ; pemphigoïdes ; pelade ; vitiligo<br>\n              <strong>Cytopénies auto-immunes :</strong> <span class=\"kw-def\">anémie hémolytique auto-immune</span> ; <span class=\"kw-def\">purpura thrombopénique immunologique</span> ; neutropénie auto-immune\n            </td>\n            <td>\n              <strong>Connectivites :</strong> <span class=\"kw-def\">polyarthrite rhumatoïde</span> ; <span class=\"kw-def\">lupus systémique</span> ; <span class=\"kw-def\">sclérodermie systémique</span> ; <span class=\"kw-def\">syndrome de Gougerot-Sjögren</span> ; <span class=\"kw-def\">myopathies inflammatoires</span> (dont syndrome des anti-synthétases) ; <span class=\"kw-def\">connectivite mixte</span><br>\n              <strong>Vascularites primitives :</strong> <span class=\"kw-def\">artérite à cellules géantes</span> (ex-Horton) ; <span class=\"kw-clinique\">Takayasu</span> ; Kawasaki ; périartérite noueuse ; <span class=\"kw-def\">granulomatose avec polyangéite</span> (ex-<span class=\"kw-clinique\">Wegener</span>) ; <span class=\"kw-def\">granulomatose éosinophilique avec polyangéite</span> (ex-<span class=\"kw-clinique\">Churg-Strauss</span>) ; polyangéite microscopique ; <span class=\"kw-def\">vascularite</span> à <span class=\"kw-chiffre\">IgA</span> (ex-<span class=\"kw-def\"><span class=\"kw-def\">purpura</span> rhumatoïde</span>) ; <span class=\"kw-def\">vascularite</span> à <span class=\"kw-bio\">anticorps anti-MBG</span> (ex-Goodpasture) ; maladie de <span class=\"kw-clinique\">Behçet</span><br>\n              <strong>À part :</strong> <span class=\"kw-def\">syndrome des antiphospholipides (SAPL)</span> ; polychondrite chronique atrophiante\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 247 — <span class=\"kw-def\">Diabète</span> · 98 — Myasthénie</em></p>","frequence":0},{"id":"192-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales familles d’autoanticorps évocatrices de maladie auto-immune systémique","contenu":"<p>Six grandes <strong>familles d'auto-anticorps</strong> orientent le diagnostic d'une MAI. Pour <span class=\"kw-clinique\">les</span> MAI <strong>systémiques</strong>, cinq familles sont en jeu (les auto-<span class=\"kw-bio\">anticorps anti-tissus</span> marquant les MAI spécifiques d'organe).</p>\n      <table >\n        <thead><tr><th>Famille d'auto-anticorps</th><th>Marqueur de</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">AC anti-nucléaires (AAN)</span></strong></td><td>MAI systémiques <strong>non vascularitiques</strong> — connectivites ++</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">AC anti-phospholipides (aPL)</span></strong></td><td><span class=\"kw-def\">SAPL</span> — anti-cardiolipine ; anti-β2-glycoprotéine 1 ; <span class=\"kw-ttt\">anticoagulant</span> circulant lupique</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Facteur rhumatoïde (FR)</span></strong></td><td><span class=\"kw-def\">Polyarthrite rhumatoïde</span> — AC anti-fragment Fc des <span class=\"kw-chiffre\">IgG</span>, marqueur <strong>peu spécifique</strong></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">AC anti-peptides citrullinés (ACPA / anti-CCP)</span></strong></td><td><span class=\"kw-def\">Polyarthrite rhumatoïde</span> — marqueur <strong>spécifique</strong> (spécificité <span class=\"kw-chiffre\">90-95 %</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">ANCA</span></strong> — anti-cytoplasme des PNN</td><td><span class=\"kw-def\">Vascularites à ANCA</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">AC anti-tissus / anti-cellules</span></strong></td><td>MAI <strong>spécifiques d'organe</strong> (rappel)</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>spécificités antigéniques des <span class=\"kw-bio\">AAN</span></strong> précisent la connectivite en cause :</p>\n      <table >\n        <thead><tr><th>Auto-anticorps</th><th>MAI évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Anti-ADN natif</span> (double brin)</td><td><span class=\"kw-def\">Lupus systémique</span> — titre <strong>corrélé à l'activité</strong> de la maladie</td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-Sm</span></td><td><span class=\"kw-def\">Lupus systémique</span> — le plus <strong>spécifique</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-RNP</span></td><td><span class=\"kw-def\">Connectivite mixte</span> (Sharp, constants) ; <span class=\"kw-def\">lupus</span> systémique</td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-Scl70</span> (anti-topoisomérase 1) ; <span class=\"kw-bio\">anti-ARN polymérase III</span></td><td><span class=\"kw-def\">Sclérodermie systémique diffuse</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-centromères</span></td><td><span class=\"kw-def\">Sclérodermie systémique cutanée limitée</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-SSA/Ro</span> ; <span class=\"kw-bio\">anti-SSB/La</span></td><td><span class=\"kw-def\">Lupus</span> systémique ; <span class=\"kw-def\">syndrome de Gougerot-Sjögren</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-ARNt synthétases</span> (dont JO1)</td><td><span class=\"kw-def\">Dermatomyosite</span> ; syndrome des anti-synthétases</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-bio\">ANCA</span></strong> se distinguent par l'aspect en <span class=\"kw-bio\">immunofluorescence</span> et la cible antigénique :</p>\n      <table >\n        <thead><tr><th>Aspect IFI</th><th>Cible antigénique</th><th>Vascularites associées</th></tr></thead>\n        <tbody>\n          <tr><td><strong>c-<span class=\"kw-bio\">ANCA</span></strong> (cytoplasmique)</td><td><span class=\"kw-bio\">Protéinase 3 (PR3)</span></td><td><span class=\"kw-def\">Granulomatose avec polyangéite</span> ++</td></tr>\n          <tr><td><strong>p-<span class=\"kw-bio\">ANCA</span></strong> (périnucléaire)</td><td><span class=\"kw-bio\">Myéloperoxydase (MPO)</span></td><td><span class=\"kw-def\">Granulomatose éosinophilique avec polyangéite</span> ; <span class=\"kw-def\">polyangéite microscopique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La sensibilité des <span class=\"kw-bio\">ANCA</span> est limitée : une recherche négative <span class=\"kw-alerte\">n'élimine pas</span> une <span class=\"kw-def\">vascularite</span> à <span class=\"kw-bio\">ANCA</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span></em></p>","frequence":4},{"id":"192-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques et biologiques des MAI non spécifiques d’organe","contenu":"<p><span class=\"kw-clinique\">Les</span> MAI <strong>non spécifiques d'organe</strong> sont les MAI <strong>systémiques</strong> : <span class=\"kw-def\">connectivites</span> et <span class=\"kw-def\">vascularites</span>. Le tableau compare les six principales connectivites.</p>\n      <table >\n        <thead><tr><th>Connectivite</th><th>Signes d'appel cliniques</th><th>Signes biologiques immunologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Lupus systémique</span></strong></td>\n            <td><span class=\"kw-clinique\">Photosensibilité</span> ; signes cutanéo-muqueux ; polyarthrite distale <strong>non érosive</strong> ; <span class=\"kw-clinique\">péricardite</span> ; <span class=\"kw-clinique\">glomérulonéphrite</span> <em>(femme de <span class=\"kw-chiffre\">20-30 ans</span>)</em></td>\n            <td><span class=\"kw-bio\">AAN</span> ; <span class=\"kw-bio\">anti-ADN natif</span> ; <span class=\"kw-bio\">anti-Sm</span> ; <span class=\"kw-bio\">anti-SSA</span>/SSB ; anti-RNP ; <span class=\"kw-bio\">hypocomplémentémie</span> en <span class=\"kw-clinique\">poussée</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Polyarthrite rhumatoïde</span></strong></td>\n            <td>Polyarthrite distale symétrique <strong>érosive</strong> <em>(femme de <span class=\"kw-chiffre\">40-60 ans</span>)</em></td>\n            <td><span class=\"kw-bio\">Facteur rhumatoïde</span> ; <span class=\"kw-bio\">ACPA (anti-CCP)</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Gougerot-Sjögren</span></strong></td>\n            <td><span class=\"kw-clinique\">Syndrome sec</span> ; parotidomégalie ; polyarthrite distale non érosive ; neuropathie périphérique</td>\n            <td><span class=\"kw-bio\">AAN</span> ; <span class=\"kw-bio\">anti-SSA</span> ; <span class=\"kw-bio\">anti-SSB</span> ; facteur rhumatoïde fréquent</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Sclérodermie systémique</span></strong></td>\n            <td><span class=\"kw-clinique\">Syndrome de Raynaud</span> ; <span class=\"kw-clinique\">sclérodactylie</span> ; ulcérations digitales ; <span class=\"kw-clinique\">RGO</span></td>\n            <td><span class=\"kw-bio\">AAN</span> (cibles mutuellement exclusives) : <span class=\"kw-bio\">anti-Scl70</span> ; anti-centromères ; anti-ARN polymérase III</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Myosites inflammatoires</span></strong></td>\n            <td><span class=\"kw-clinique\">Faiblesse musculaire proximale</span> ; amyotrophie ; <span class=\"kw-clinique\">arthralgies</span> ; élévation des enzymes musculaires</td>\n            <td><span class=\"kw-bio\">AAN</span> ; <span class=\"kw-bio\">anti-JO1</span> ; anti-Mi2 ; anti-MDA5 ; anti-SRP</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Connectivite mixte</span></strong> (Sharp)</td>\n            <td><span class=\"kw-def\">Syndrome de Raynaud</span> ; synovites ; <span class=\"kw-clinique\">myalgies</span></td>\n            <td><span class=\"kw-bio\">Anti-RNP</span> à titre élevé</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Repères discriminants.</strong> Polyarthrite <strong>érosive</strong> → <span class=\"kw-clinique\">PR</span> ; polyarthrite <strong>non érosive</strong> → <span class=\"kw-def\">lupus</span> ou <span class=\"kw-clinique\">Sjögren</span>. Le <span class=\"kw-alerte\">lymphome de MALT</span> complique <span class=\"kw-chiffre\">5-10 %</span> des Sjögren suivis plus de <span class=\"kw-chiffre\">15 ans</span>. Une <span class=\"kw-def\">dermatomyosite</span> est <strong><span class=\"kw-etio\">paranéoplasique</span> dans <span class=\"kw-chiffre\">30-50 %</span></strong> des cas — chercher le cancer.\n      </div>\n      <p>La <strong><span class=\"kw-clinique\">sclérodermie</span> systémique</strong> (mnémo <strong>CREST</strong> : <span class=\"kw-clinique\">Calcinose</span>, Raynaud, atteinte œsophagienne, Sclérodactylie, Télangiectasies) se décline en deux phénotypes, à <strong>distinguer</strong> :</p>\n      <table >\n        <thead><tr><th>Phénotype</th><th>Atteinte cutanée</th><th>Auto-anticorps</th><th>Complication d'organe</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Forme diffuse</strong></td><td>Peut toucher tout le corps</td><td><span class=\"kw-bio\">Anti-Scl70</span> ; anti-ARN polymérase III</td><td><span class=\"kw-imagerie\">PID</span> ; <span class=\"kw-alerte\">crise rénale sclérodermique</span></td></tr>\n          <tr><td><strong>Forme limitée</strong> (ex-CREST)</td><td><strong>Ne remonte pas au-dessus des coudes</strong></td><td><span class=\"kw-bio\">Anti-centromères</span></td><td><span class=\"kw-alerte\">HTAP</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — <span class=\"kw-alerte\">crise rénale sclérodermique</span>.</strong> Association <span class=\"kw-alerte\">HTA sévère</span> + <span class=\"kw-alerte\">microangiopathie thrombotique</span> + <span class=\"kw-alerte\">insuffisance rénale aiguë</span> rapidement progressive. Traitement à instaurer <strong>en urgence</strong> par <span class=\"kw-ttt\">IEC</span>. Une <span class=\"kw-ttt\">corticothérapie</span> &gt; <span class=\"kw-chiffre\">10 mg/j</span> en augmente le risque.\n      </div>\n      <p>Sur le plan <span class=\"kw-ttt\">biologique</span>, le <strong><span class=\"kw-def\">syndrome inflammatoire</span></strong> est inconstant ; une <strong>dissociation <span class=\"kw-bio\">VS</span>-<span class=\"kw-bio\">CRP</span></strong> (<span class=\"kw-bio\">VS</span> élevée, <span class=\"kw-bio\">CRP</span> normale) est typique du <span class=\"kw-def\">lupus</span> et du <span class=\"kw-clinique\">Sjögren</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 193 — <span class=\"kw-def\">Vascularite</span> systémique</em></p>","frequence":3},{"id":"192-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques et biologiques des MAI spécifiques d’organe","contenu":"<p>Une MAI <strong>spécifique d'organe</strong> associe l'atteinte d'un organe à des <strong>auto-<span class=\"kw-bio\">anticorps anti-tissus</span>, anti-cellules ou anti-récepteurs</strong>, marqueurs de l'organe ciblé.</p>\n      <table >\n        <thead><tr><th>Organe</th><th>Maladie <span class=\"kw-etio\">auto-immune</span></th><th>Auto-anticorps</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Thyroïde</strong></td><td><span class=\"kw-def\">Thyroïdite de Hashimoto</span></td><td><span class=\"kw-bio\">Anti-thyroperoxydase (TPO)</span> ++ ; anti-thyroglobuline</td></tr>\n          <tr><td><strong>Thyroïde</strong></td><td><span class=\"kw-def\">Maladie de Basedow</span></td><td><span class=\"kw-bio\">Anti-récepteur de la TSH (TRAK)</span> — spécifiques, corrélés à l'activité</td></tr>\n          <tr><td><strong>Estomac</strong></td><td><span class=\"kw-def\">Maladie de Biermer</span></td><td>Anti-cellules pariétales gastriques ; anti-facteur intrinsèque</td></tr>\n          <tr><td><strong>Peau</strong></td><td><span class=\"kw-def\">Pemphigus</span> / pemphigoïde</td><td><span class=\"kw-bio\">Anti-desmogléine</span> 1 (superficiel) et 3 (vulgaire) ; anti-BPAG (pemphigoïde)</td></tr>\n          <tr><td><strong>Pancréas</strong></td><td><span class=\"kw-def\">Diabète de type 1</span></td><td><span class=\"kw-bio\">Anti-GAD</span> ; anti-IA2 ; anti-ZnT8 ; anti-<span class=\"kw-ttt\">insuline</span> (<span class=\"kw-chiffre\">≥ 1</span> auto-AC dans <span class=\"kw-chiffre\">97 %</span>)</td></tr>\n          <tr><td><strong>Jonction neuromusculaire</strong></td><td><span class=\"kw-def\">Myasthénie</span></td><td><span class=\"kw-bio\">Anti-récepteur de l'acétylcholine (RACh)</span> — <strong>affirme le diagnostic</strong> ; anti-MuSK si RACh négatifs</td></tr>\n          <tr><td><strong>Jonction neuromusculaire</strong></td><td><span class=\"kw-def\">Syndrome de Lambert-Eaton</span></td><td>Anti-canaux calciques</td></tr>\n          <tr><td><strong>Intestin grêle</strong></td><td><span class=\"kw-def\">Maladie cœliaque</span></td><td><span class=\"kw-bio\">Anti-transglutaminase IgA</span> + <span class=\"kw-chiffre\">IgA</span> totales (1ʳᵉ intention) ; anti-endomysium</td></tr>\n          <tr><td><strong>Surrénale</strong></td><td><span class=\"kw-def\">Maladie d'Addison</span></td><td>Anti-21-hydroxylase</td></tr>\n          <tr><td><strong>Foie</strong></td><td><span class=\"kw-def\">Cirrhose biliaire primitive</span></td><td>Anti-mitochondries</td></tr>\n          <tr><td><strong>Système nerveux</strong></td><td><span class=\"kw-def\">Neuromyélite optique de Devic</span> ; <span class=\"kw-def\">Guillain-Barré</span></td><td>Anti-aquaporine 4 (anti-NMO) ; anti-gangliosides (Guillain-Barré)</td></tr>\n          <tr><td><strong>Rein</strong></td><td><span class=\"kw-def\">Glomérulonéphrite extra-membraneuse</span> idiopathique</td><td>Anti-PLA2R</td></tr>\n          <tr><td><strong>Lignées sanguines</strong></td><td><span class=\"kw-def\">Cytopénies auto-immunes</span></td><td>AHAI → <span class=\"kw-bio\">test de Coombs</span> ; PTI → anti-<span class=\"kw-bio\">plaquettes</span> (MAIPA) ; neutropénie → anti-PNN</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 98 — Myasthénie · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":0},{"id":"192-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales anomalies immunologiques et du complément","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>anomalies immunologiques</strong> d'une MAI correspondent aux <span class=\"kw-bio\">auto-anticorps</span>. Points clés :</p>\n      <ul>\n        <li>utiles au diagnostic, mais de <strong>sensibilité et spécificité variables</strong> ;</li>\n        <li>leur seule présence est <span class=\"kw-alerte\">insuffisante</span> pour affirmer le diagnostic ;</li>\n        <li>ils ne sont <strong>pas tous pathogènes</strong> — certains ne sont que des <em>marqueurs</em> ;</li>\n        <li>certaines MAI <strong>n'ont pas d'auto-anticorps</strong> (ex. <span class=\"kw-def\">sclérose en plaques</span>).</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> <strong>anomalies du <span class=\"kw-bio\">complément</span></strong> (<span class=\"kw-bio\">C3</span>, C4, CH50) reflètent l'activation immunitaire :</p>\n      <table >\n        <thead><tr><th>Anomalie du complément</th><th>Mécanisme et MAI associées</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Hypocomplémentémie de consommation</span></strong> (baisse <span class=\"kw-bio\">C3</span>, C4, CH50)</td><td>Cryoglobulinémies ; <span class=\"kw-def\">lupus systémique</span> (utile à la <span class=\"kw-def\">surveillance</span> — associée à une forme plus sévère) ; <span class=\"kw-def\">vascularites</span> en <span class=\"kw-clinique\">poussée</span> ; dépôts de complexes immuns activant la voie classique</td></tr>\n          <tr><td><strong>Déficit en <span class=\"kw-bio\">complément</span> <span class=\"kw-etio\">génétique</span></strong></td><td><span class=\"kw-alerte\">Prédispose au lupus</span> — déficits en <span class=\"kw-bio\">C1q</span>, <span class=\"kw-bio\">C2</span>, <span class=\"kw-bio\">C4</span></td></tr>\n          <tr><td><strong>Hypercomplémentémie</strong></td><td>Observée au cours du <span class=\"kw-def\">syndrome inflammatoire</span> — la plupart des maladies systémiques ou infectieuses</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 185 — Réaction <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":0},{"id":"192-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les anomalies biologiques (hémogramme et électrophorèse des protéines)","contenu":"<p>Devant une MAI, l'<strong><span class=\"kw-bio\">hémogramme</span></strong> et l'<strong><span class=\"kw-bio\">électrophorèse des protéines sériques</span> (<span class=\"kw-bio\">EPS</span>)</strong> apportent des anomalies non spécifiques mais orientantes.</p>\n      <p><strong><span class=\"kw-bio\">Hémogramme</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Thrombopénie</span> — PTI primaire ou secondaire (ex. <span class=\"kw-def\">lupus</span> systémique) ;</li>\n        <li><span class=\"kw-clinique\">Thrombocytose</span> — <span class=\"kw-def\">syndrome inflammatoire</span> chronique ;</li>\n        <li><span class=\"kw-clinique\">Leucopénie</span> (neutropénie ou lymphopénie) — fréquente dans <span class=\"kw-clinique\">les</span> MAI systémiques, souvent d'origine périphérique ;</li>\n        <li><span class=\"kw-clinique\">Hyperleucocytose</span> — certaines vascularites, maladie de Still.</li>\n      </ul>\n      <p>L'<strong>anémie</strong> d'une MAI relève de <strong>5 mécanismes</strong> à raisonner systématiquement :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Marqueur clé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Anémie hémolytique <span class=\"kw-etio\">auto-immune</span></strong></td><td><span class=\"kw-bio\">Test de Coombs direct</span> positif (AC anti-globule rouge)</td></tr>\n          <tr><td><strong>Microangiopathie <span class=\"kw-etio\">thrombotique</span></strong></td><td><span class=\"kw-bio\">Schizocytes</span> au frottis + <span class=\"kw-bio\">thrombopénie</span> de consommation</td></tr>\n          <tr><td><strong>Carence martiale</strong></td><td>Malabsorption (<span class=\"kw-etio\">maladie cœliaque</span>)</td></tr>\n          <tr><td><strong>Anémie <span class=\"kw-etio\">inflammatoire</span></strong></td><td><span class=\"kw-def\">Syndrome inflammatoire</span> chronique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Insuffisance rénale chronique</span></strong></td><td>Ex. néphropathie lupique</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-bio\">VS</span> et <span class=\"kw-bio\">CRP</span></strong> : le <span class=\"kw-def\">syndrome inflammatoire</span> est <strong>inconstant</strong>. Une <strong>dissociation <span class=\"kw-bio\">VS</span>-<span class=\"kw-bio\">CRP</span></strong> (<span class=\"kw-bio\">VS</span> augmentée, <span class=\"kw-bio\">CRP</span> normale sauf sérite ou infection) est typique du <span class=\"kw-def\">lupus</span> et du <span class=\"kw-def\">syndrome de Sjögren</span>.</p>\n      <p><strong><span class=\"kw-bio\">Électrophorèse des protéines</span> (<span class=\"kw-bio\">EPS</span>)</strong> :</p>\n      <table >\n        <thead><tr><th>Anomalie <span class=\"kw-bio\">EPS</span></th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td>Hypoalbuminémie + <span class=\"kw-bio\">hyper-α2-globulinémie</span></td><td><span class=\"kw-def\">Syndrome inflammatoire</span></td></tr>\n          <tr><td><strong>Hypergammaglobulinémie polyclonale globale</strong></td><td>Forte activation B — <span class=\"kw-def\">lupus systémique</span>, <span class=\"kw-def\">syndrome de Sjögren</span></td></tr>\n          <tr><td>Hypergammaglobulinémie prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">IgG</span></td><td>Hépatites auto-immunes</td></tr>\n          <tr><td>Hypergammaglobulinémie prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">IgM</span></td><td><span class=\"kw-def\">Cirrhose</span> biliaire primitive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> L'<span class=\"kw-alerte\">hypergammaglobulinémie polyclonale</span> augmente la <span class=\"kw-bio\">VS</span> mais <strong>n'est pas un marqueur du <span class=\"kw-def\">syndrome inflammatoire</span></strong> au sens strict : elle reflète une stimulation polyclonale chronique des <span class=\"kw-bio\">lymphocytes</span> B (<span class=\"kw-etio\">auto-immune</span>, infectieuse ou hépatique), pas l'inflammation.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 215 — <span class=\"kw-def\">Purpura</span> · 185 — Réaction <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":3},{"id":"192-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la notion de titre significatif (pour une recherche d’anticorps anti-nucléaires)","contenu":"<p>Le <strong><span class=\"kw-def\">dépistage</span> des <span class=\"kw-bio\">anticorps anti-nucléaires</span> (<span class=\"kw-bio\">AAN</span>)</strong> se fait par <span class=\"kw-bio\">immunofluorescence indirecte (IFI)</span> sur cellules tumorales humaines en culture (<strong>HEp-2</strong>) ou sur coupes de foie de rat.</p>\n      <p>Le <strong>titre</strong> correspond à la <strong>dilution la plus forte</strong> pour laquelle la fluorescence reste positive. Seuils de positivité :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">&gt; 1/80</span> — seuil retenu pour le <span class=\"kw-def\">lupus</span> ;</li>\n        <li><span class=\"kw-chiffre\">&gt; 1/160</span> — seuil retenu pour <span class=\"kw-clinique\">les</span> MAI en général.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — sens du titre.</strong> Un titre de <span class=\"kw-chiffre\">1/16</span> témoigne d'une concentration <strong>moindre</strong> qu'un titre de <span class=\"kw-chiffre\">1/128</span> : plus le dénominateur est grand, plus l'échantillon était concentré (il a fallu davantage de dilutions avant d'obtenir un test négatif).\n      </div>\n      <p>L'<strong>aspect de la fluorescence</strong> oriente <span class=\"kw-clinique\">les</span> tests complémentaires (réalisés uniquement si le titre est positif) vers la cible antigénique :</p>\n      <table >\n        <thead><tr><th>Aspect de fluorescence</th><th>Cibles antigéniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Homogène</strong></td><td><span class=\"kw-bio\">Anti-ADN natif</span> ; anti-Histone (auto-AC insolubles)</td></tr>\n          <tr><td><strong>Moucheté à gros grains</strong></td><td><span class=\"kw-bio\">Anti-Sm</span> ; <span class=\"kw-bio\">anti-RNP</span></td></tr>\n          <tr><td><strong>Moucheté fin</strong></td><td><span class=\"kw-bio\">Anti-SSA/Ro</span> ; <span class=\"kw-bio\">anti-SSB</span>/La</td></tr>\n          <tr><td><strong>Nucléolaire</strong></td><td><span class=\"kw-bio\">Anti-Scl70</span> ; anti-PM/Scl</td></tr>\n          <tr><td><strong>Centromérique</strong></td><td><span class=\"kw-bio\">Anti-centromères</span> — <span class=\"kw-def\">sclérodermie</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/192/aan-ifi-patterns.png\" alt=\"Aspects de fluorescence des anticorps anti-nucléaires en immunofluorescence indirecte sur cellules HEp-2\" loading=\"lazy\">\n        <figcaption>Aspects de fluorescence des <span class=\"kw-bio\">AAN</span> en <span class=\"kw-bio\">immunofluorescence</span> indirecte sur cellules HEp-2, orientant la recherche de la cible antigénique. Source : fiche source EDN item 192.</figcaption>\n      </figure>","frequence":0},{"id":"192-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux objectifs thérapeutiques et principes généraux des traitements des maladies auto-immunes systémiques","contenu":"<p>La prise en charge des MAI systémiques s'organise, idéalement au sein de <strong>centres de référence maladies rares</strong>, autour de <strong>trois axes thérapeutiques</strong>.</p>\n      <table >\n        <thead><tr><th>Axe thérapeutique</th><th>Moyens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Traitement des poussées</strong></td><td>Symptomatique (<span class=\"kw-ttt\">antalgiques</span>, <span class=\"kw-ttt\">AINS</span>) ; <span class=\"kw-ttt\">corticothérapie</span> ; <span class=\"kw-ttt\">immunosuppresseurs</span> ; traitement local (<span class=\"kw-ttt\">infiltration</span> intra-articulaire de <span class=\"kw-ttt\">corticoïdes</span>)</td></tr>\n          <tr><td><strong>Traitement de fond / d'entretien</strong><br>(contrôle de l'activité, prévention des rechutes, épargne cortisonique)</td><td><span class=\"kw-ttt\">Immunosuppresseurs</span> ; immunomodulateurs ; <span class=\"kw-ttt\">biothérapies</span> ; <span class=\"kw-ttt\">Ig IV polyvalentes</span> ; échanges plasmatiques ; autogreffe de CSH</td></tr>\n          <tr><td><strong>Traitement spécifique substitutif</strong></td><td><span class=\"kw-ttt\">Insuline</span> (<span class=\"kw-def\"><span class=\"kw-def\">diabète</span> de type 1</span>) ; <span class=\"kw-ttt\">hormones thyroïdiennes</span> (Hashimoto) ; <span class=\"kw-ttt\">vitamine B12</span> (Biermer)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Corticothérapie</span></strong> : <span class=\"kw-ttt\">prednisone</span> ou <span class=\"kw-ttt\">prednisolone</span> per os en 1ʳᵉ intention ; <strong>bolus de <span class=\"kw-ttt\">méthylprednisolone</span></strong> (<span class=\"kw-chiffre\">1 à 3 jours</span>) réservés aux formes agressives menaçant le <span class=\"kw-alerte\">pronostic vital</span> ou d'organe (cœur, rein, cerveau, poumon).</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ttt\">Immunosuppresseurs</span> — sécurité.</strong> La grande majorité sont <span class=\"kw-alerte\">tératogènes</span> et imposent une <strong>contraception</strong>, <strong>SAUF <span class=\"kw-ttt\">azathioprine</span> et <span class=\"kw-ttt\">hydroxychloroquine</span></strong>. Risque de <span class=\"kw-alerte\">cytopénie</span> et d'<span class=\"kw-alerte\">infection</span> → consulter en <span class=\"kw-alerte\">urgence</span> en cas de <span class=\"kw-clinique\">fièvre</span>.\n      </div>\n      <p><strong>Mesures associées</strong> :</p>\n      <ul>\n        <li>contrôle des <strong><span class=\"kw-def\">facteurs de risque</span> cardiovasculaire</strong> — risque <span class=\"kw-bio\">CV</span> accru dans <span class=\"kw-clinique\">les</span> MAI ;</li>\n        <li>mesures associées à la <span class=\"kw-ttt\">corticothérapie</span> et aux <span class=\"kw-ttt\">immunosuppresseurs</span> ;</li>\n        <li><span class=\"kw-ci\">vaccins vivants contre-indiqués</span> sous <span class=\"kw-ttt\">immunosuppresseur</span> <strong>ou</strong> <span class=\"kw-ttt\">corticothérapie</span> &gt; <span class=\"kw-chiffre\">10 mg/j</span> ;</li>\n        <li>mesures sociales : <strong><span class=\"kw-def\">ALD</span></strong>, RQTH ;</li>\n        <li>rééducation : kinésithérapie, ergothérapie, orthèses.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Suivi</span>.</strong> <span class=\"kw-clinique\">Évolution</span> imprévisible → suivi régulier adapté au cas par cas. Le taux de certains auto-anticorps est corrélé à l'activité et utile au suivi : <span class=\"kw-bio\">anti-ADN</span>, <span class=\"kw-bio\">ANCA</span>, <span class=\"kw-bio\">anti-TRAK</span>, <span class=\"kw-bio\">anti-RACh</span>, <span class=\"kw-bio\">anti-transglutaminase IgA</span>. <span class=\"kw-clinique\">Les</span> grossesses ne sont pas <span class=\"kw-ci\">contre-indiquées</span> mais doivent être <strong>discutées</strong> selon la maladie et les traitements.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 202 — Biothérapies, thérapies ciblées</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-13-0.php","label":"Collège (COFER) — Item cours 1 13 0"},{"href":"https://radiopaedia.org/articles/sjogren-syndrome-1","label":"Radiopaedia : Sjogren syndrome 1"},{"href":"https://radiopaedia.org/articles/scleroderma","label":"Radiopaedia : Scleroderma"}],"cards":[{"i":"0eefcf63f8f1","n":192,"o":"192-1","u":"Définition","t":"Connaître la définition de l’auto-immunité","q":"Quelle est la définition d'une maladie auto-immune (MAI) et qu'est-ce qui la distingue de l'auto-immunité physiologique ?","a":"<p>Une maladie auto-immune (MAI) est caractérisée par une <strong>rupture des mécanismes de tolérance</strong> du système immunitaire envers les constituants du soi. Contrairement à l'auto-immunité physiologique, la MAI se manifeste par :</p><ul><li>Des <strong>conséquences cliniques, biologiques, histologiques ou d'imagerie</strong> résultant d'une réaction immunitaire contre les antigènes du soi.</li><li>La présence d'<strong>auto-anticorps</strong> et/ou de <strong>lymphocytes auto-réactifs</strong> dans un organe atteint.</li></ul>"},{"i":"18fbe4da42bd","n":192,"o":"192-1","u":"Définition","t":"Connaître la définition de l’auto-immunité","q":"Comment définit-on une maladie auto-immune sévère ?","a":"<p>Une maladie auto-immune sévère est définie par l'existence de <strong>lésions d'organes « nobles »</strong>, tels que le <strong>rein, le poumon, le SNC, le SNP, le cœur, le tube digestif ou le système hématopoïétique</strong>. Cette sévérité engage le pronostic vital et justifie un <strong>traitement agressif</strong>.</p>"},{"i":"317faa5f6743","n":192,"o":"192-1","u":"Définition","t":"Connaître la définition de l’auto-immunité","q":"Qu'est-ce que l'auto-immunité en médecine ?","a":"<p>L'auto-immunité est un phénomène <strong>physiologique naturel</strong> où le système immunitaire produit en permanence des <strong>auto-anticorps</strong> et des <strong>lymphocytes auto-réactifs</strong>. Ces éléments sont contrôlés par des mécanismes de tolérance vis-à-vis des antigènes du soi.</p>"},{"i":"a01543dba39b","n":192,"o":"192-1","u":"Définition","t":"Connaître la définition de l’auto-immunité","q":"Quel est le piège majeur à éviter lors du diagnostic d'une maladie auto-immune (MAI) ?","a":"<p>Le piège majeur est de ne pas considérer la <strong>seule présence d'auto-anticorps</strong> (signe biologique) sans signes cliniques, histologiques ou d'imagerie comme suffisante pour poser le diagnostic de MAI. Toute <strong>stimulation du système immunitaire</strong> (notamment une infection) peut générer transitoirement des auto-anticorps sans qu'il y ait pour autant une MAI.</p>"},{"i":"02a91357d6f6","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) non classées dans les catégories classiques, mais listées comme systémiques.","a":"<p>Des exemples de MAI non classées ainsi, mais systémiques, sont :</p><ul><li>Le <strong>syndrome des antiphospholipides (SAPL)</strong></li><li>La <strong>polychondrite chronique atrophiante</strong></li></ul>"},{"i":"33a3e5cb6ce6","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) spécifiques d'organes touchant le système nerveux.","a":"<p>Les MAI spécifiques d'organes touchant le système nerveux incluent :</p><ul><li>La <strong>myasthénie</strong></li><li>Le <strong>syndrome de Lambert-Eaton</strong></li><li>Le <strong>syndrome de Guillain-Barré</strong></li><li>La <strong>sclérose en plaques</strong></li></ul>"},{"i":"4d463d11fdfc","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) spécifiques d'organes touchant la peau ou les cytopénies auto-immunes.","a":"<p>Les MAI spécifiques d'organes sont :</p><ul><li>Pour la <strong>peau</strong> : le <strong>pemphigus</strong>, les <strong>pemphigoïdes</strong>, la <strong>pelade</strong>, le <strong>vitiligo</strong>.</li><li>Pour les <strong>cytopénies auto-immunes</strong> : l'<strong>anémie hémolytique auto-immune</strong>, le <strong>purpura thrombopénique immunologique (PTI)</strong>, la <strong>neutropénie auto-immune</strong>.</li></ul>"},{"i":"7fc61e7bea56","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) spécifiques d'organes touchant les glandes endocrines.","a":"<p>Les MAI spécifiques d'organes touchant les glandes endocrines incluent :</p><ul><li>La <strong>thyroïdite de Hashimoto</strong></li><li>La <strong>maladie de Basedow</strong></li><li>La <strong>maladie d'Addison</strong></li><li>Le <strong>diabète de type 1</strong></li><li>L'<strong>ovarite auto-immune</strong></li></ul>"},{"i":"c7887ef211be","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) spécifiques d'organes touchant le foie et le tube digestif.","a":"<p>Les MAI spécifiques d'organes touchant le foie et le tube digestif incluent :</p><ul><li>Les <strong>hépatites auto-immunes</strong></li><li>La <strong>cirrhose biliaire primitive</strong></li><li>La <strong>maladie de Biermer</strong></li><li>La <strong>maladie cœliaque</strong></li></ul>"},{"i":"e0adb137a2b7","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) systémiques de type connectivites.","a":"<p>Les MAI systémiques de type connectivites incluent :</p><ul><li>La <strong>polyarthrite rhumatoïde</strong></li><li>Le <strong>lupus systémique</strong></li><li>La <strong>sclérodermie systémique</strong></li><li>Le <strong>syndrome de Gougerot-Sjögren</strong></li><li>Les <strong>myopathies inflammatoires</strong> (dont le syndrome des anti-synthétases)</li><li>La <strong>connectivite mixte</strong></li></ul>"},{"i":"fa5c21d4c822","n":192,"o":"192-3","u":"Définition","t":"Citer des exemples de MAI spécifique d’organe et systémiques","q":"Citez des exemples de maladies auto-immunes (MAI) systémiques de type vascularites primitives.","a":"<p>Les MAI systémiques de type vascularites primitives incluent :</p><ul><li>L'<strong>artérite à cellules géantes</strong> (ex-Horton)</li><li>La maladie de <strong>Takayasu</strong></li><li>La maladie de <strong>Kawasaki</strong></li><li>La <strong>périartérite noueuse</strong></li><li>La <strong>granulomatose avec polyangéite</strong> (ex-Wegener)</li><li>La <strong>granulomatose éosinophilique avec polyangéite</strong> (ex-Churg-Strauss)</li><li>La <strong>polyangéite microscopique</strong></li><li>La <strong>vascularite à IgA</strong> (ex-purpura rhumatoïde)</li><li>La <strong>vascularite à anticorps anti-MBG</strong> (ex-Goodpasture)</li><li>La maladie de <strong>Behçet</strong></li></ul>"},{"i":"31d5ce996df4","n":192,"o":"192-8","u":"Examens complémentaires","t":"Connaître les anomalies biologiques (hémogramme et électrophorèse des protéines)","q":"Quelle est la signification de l'hypergammaglobulinémie polyclonale dans le cadre d'une maladie auto-immune ?","a":"<p>L'hypergammaglobulinémie polyclonale augmente la VS (Vitesse de Sédimentation), mais n'est pas un marqueur spécifique de syndrome inflammatoire. Elle reflète une <strong>stimulation polyclonale chronique des lymphocytes B</strong> d'origine auto-immune, infectieuse ou hépatique.</p>"},{"i":"5bf5b39ed40f","n":192,"o":"192-8","u":"Examens complémentaires","t":"Connaître les anomalies biologiques (hémogramme et électrophorèse des protéines)","q":"Quelles anomalies de l'hémogramme peuvent être observées dans les pathologies auto-immunes ?","a":"<p>Dans les pathologies auto-immunes, l'hémogramme peut révéler :</p><ul><li>Une <strong>thrombopénie</strong> : PTI primaire ou secondaire (ex. lupus systémique).</li><li>Une <strong>thrombocytose</strong> : syndrome inflammatoire chronique.</li><li>Une <strong>leucopénie</strong> (neutropénie ou lymphopénie) : fréquente dans les MAI systémiques, souvent d'origine périphérique.</li><li>Une <strong>hyperleucocytose</strong> : certaines vascularites, maladie de Still.</li></ul>"},{"i":"b378c3cad4ec","n":192,"o":"192-8","u":"Examens complémentaires","t":"Connaître les anomalies biologiques (hémogramme et électrophorèse des protéines)","q":"Quels sont les cinq mécanismes d'anémie à rechercher systématiquement en cas de maladie auto-immune et leurs marqueurs clés ?","a":"<p>Les cinq mécanismes d'anémie et leurs marqueurs clés sont :</p><ul><li><strong>Anémie hémolytique auto-immune</strong> : <strong>Test de Coombs direct positif</strong> (anticorps anti-globule rouge).</li><li><strong>Microangiopathie thrombotique</strong> : <strong>schizocytes</strong> au frottis et thrombopénie de consommation.</li><li><strong>Carence martiale</strong> : malabsorption (ex. maladie cœliaque).</li><li><strong>Anémie inflammatoire</strong> : syndrome inflammatoire chronique.</li><li><strong>Insuffisance rénale chronique</strong> : ex. néphropathie lupique.</li></ul>"},{"i":"cc4414b92a58","n":192,"o":"192-8","u":"Examens complémentaires","t":"Connaître les anomalies biologiques (hémogramme et électrophorèse des protéines)","q":"Que peut révéler l'électrophorèse des protéines sériques (EPS) en cas de maladie auto-immune ?","a":"<p>L'électrophorèse des protéines sériques (EPS) peut mettre en évidence :</p><ul><li>Une <strong>hypoalbuminémie</strong> et une <strong>hyper-α2-globulinémie</strong> : témoin d'un syndrome inflammatoire.</li><li>Une <strong>hypergammaglobulinémie polyclonale globale</strong> : forte activation B (lupus systémique, syndrome de Sjögren).</li><li>Une <strong>hypergammaglobulinémie prédominant sur les IgG</strong> : hépatites auto-immunes.</li><li>Une <strong>hypergammaglobulinémie prédominant sur les IgM</strong> : cirrhose biliaire primitive.</li></ul>"}]};